parameters.jsCode:
// Expected body: { email, name?, payload } where payload conforms to engine/input_contract.md
const b = $input.first().json.body ?? $input.first().json;
if (!b.email || !b.payload) { throw new Error('Body must include email and payload (input_contract client payload)'); }
return [{ json: { email: String(b.email).trim().toLowerCase(), name: b.name || b.email, payload: b.payload } }];

// The engine returns a program that already passed the QC gate, or UNSATISFIABLE_CONSTRAINTS.
const res = $input.first().json;
const body = res.body ?? res;
const req = $('Validate Request').first().json;
const unsatisfiable = res.statusCode >= 400 || body.error === 'UNSATISFIABLE_CONSTRAINTS' || (body.detail && String(JSON.stringify(body.detail)).includes('UNSATISFIABLE'));
return [{ json: {
  email: req.email,
  name: req.name,
  ok: !unsatisfiable,
  runId: body.run_id || body.id || '',
  progression: body.progression_flag || body.progression || 'maintain',
  reasons: unsatisfiable ? JSON.stringify(body.reasons || body.detail || body.error || res.statusCode) : '',
  weekStart: new Date().toISOString().slice(0, 10)
} }];

